      console.log('!! ARGPARSE', f, JSON.stringify(s), se.trim().split('\n').slice(0, 2).join(' | '));
    }
  }
}
console.log('files=' + files.length, 'rc0=' + ok, 'rcErr=' + err, 'distinct=' + seen.size);
